/**
 * @method
 * @name scwin.tx_fn_FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/filedownqna.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = async function () {
    /* sdd-asis-lifecycle:begin fn_goList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchQnaList');
    { const nr = await scwin.tx_fn_goList(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17300/jldfil17300.xml", { "method": 'searchQnaList' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteGoListReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnAttachSeq
 * @returns
 * @hidden N
*/
scwin.deleteGoListReq = async function (contnId, contnAttachSeq) {
    /* sdd-asis-lifecycle:begin fn_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'deleteQuestion');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    await scwin.tx_fn_delete();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnAttachSeq
 * @returns
 * @hidden N
*/
scwin.modify = async function (contnId, contnAttachSeq) {
    /* sdd-asis-lifecycle:begin fn_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'modifyQna');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_goListReq').set('modifyYn', 'Y');
    { const nr = await scwin.tx_fn_modify(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17301/jldfil17301.xml", { "method": 'modifyQna', "contnId": contnId, "contnAttachSeq": contnAttachSeq, "modifyYn": 'Y' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnAttachSeq attachFileNm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, contnAttachSeq, attachFileNm) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'filedownqna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchQnaFile');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_goListReq').set('attachFileNm', attachFileNm);
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};
